fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();

    // If length is 0 or 1, return unchanged.
    if n <= 1 {
        return numbers;
    }

    // Result length = 2*n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    for i in 0..n {
        // Insert the original element at even indices in result.
        result.push(numbers[i]);

        // Insert delimiter after each element except the last.
        if i != n - 1 {
            result.push(delimiter);
        }
    }

    result
}